<?php
namespace App\Services;use App\Models\LivenessChallenge;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class LivenessService{private const INSTRUCTIONS=['Gira lentamente la cabeza a la izquierda y vuelve al centro.','Gira lentamente la cabeza a la derecha y vuelve al centro.','Parpadea dos veces y mira de frente.','Inclina ligeramente la cabeza hacia arriba y vuelve al centro.'];public function issue(int $userId):array{LivenessChallenge::where('user_id',$userId)->whereNull('consumed_at')->update(['expires_at'=>now()]);$token=Str::random(64);$challenge=LivenessChallenge::create(['user_id'=>$userId,'token_hash'=>hash('sha256',$token),'instruction'=>self::INSTRUCTIONS[array_rand(self::INSTRUCTIONS)],'expires_at'=>now()->addMinutes(3)]);return ['token'=>$token,'instruction'=>$challenge->instruction,'expires_at'=>$challenge->expires_at->toIso8601String()];}public function consume(int $userId,string $token):LivenessChallenge{return DB::transaction(function()use($userId,$token){$challenge=LivenessChallenge::where('token_hash',hash('sha256',$token))->lockForUpdate()->first();if(!$challenge||$challenge->user_id!==$userId||$challenge->consumed_at||$challenge->expires_at->isPast())throw \Illuminate\Validation\ValidationException::withMessages(['liveness_token'=>'El desafio de presencia vencio o ya fue usado. Activa nuevamente la camara.']);$challenge->update(['consumed_at'=>now()]);return $challenge;});}}